package org.dextur.reputation.storage;
import java.nio.file.*;
import java.util.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.recovery.*;
import org.dextur.reputation.domain.recovery.RecoveryData.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.dextur.reputation.storage.RecoveryFixtures.*;
class LocalRecoveryTest {
 @org.junit.jupiter.api.io.TempDir Path directory;
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void lifecycleCapsTrustTierAndNoFakeVotes(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.lifecycle(b,directory);}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void concurrentEnrollmentAndReward(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.concurrency(b,directory);}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void pauseResumeLockAndProgress(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.pause(b,directory);}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void providerUnavailableDuplicateConflictAndStale(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.provider(b,directory);}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void daysDedupSessionReplayAndExpiry(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.daysAndReplay(b,directory);}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void programDefinitionFrozen(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.frozen(b,directory);}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void restartPreservesAllRecordsAndNoReplay(StorageType type)throws Exception{StorageSnapshot before;try(var b=StorageFixtures.local(directory,type,false)){before=complete(b,directory);}try(var b=StorageFixtures.local(directory,type,false)){assertEquals(before,b.snapshot());b.tiers(TierConfiguration.load(directory));b.recovery(rules(RecoveryRules.Type.ACTIVE_PLAYTIME));assertTrue(b.recover(request(Command.READ,NOW.plusSeconds(21))).events().isEmpty());assertEquals(before,b.snapshot());}}
 @Test void sqliteRewardFailureRollsBackProgressTrustAndTier()throws Exception{try(var b=SqlStorage.sqlite(directory.resolve("test.sqlite"),250,false)){seed(b,directory,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));b.recover(request(Command.START,NOW));b.recover(sample(NOW,0,0));var before=b.snapshot();try(var c=b.connect();var s=c.createStatement()){s.execute("CREATE TRIGGER recovery_failure BEFORE UPDATE ON dr_recovery BEGIN SELECT RAISE(FAIL,'simulated'); END");}assertThrows(Exception.class,()->b.recover(sample(NOW.plusSeconds(10),10,10)));assertEquals(before,b.snapshot());}}
 @ParameterizedTest @EnumSource(JsonStorage.Point.class)void jsonCrashHasAllOrNoneOfReward(JsonStorage.Point point)throws Exception{var fail=new java.util.concurrent.atomic.AtomicBoolean();StorageSnapshot before;try(var b=new JsonStorage(directory.resolve("json"),1048576,false,p->{if(fail.get()&&p==point)throw new java.io.IOException("simulated");})){seed(b,directory,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));b.recover(request(Command.START,NOW));b.recover(sample(NOW,0,0));before=b.snapshot();fail.set(true);assertThrows(Exception.class,()->b.recover(sample(NOW.plusSeconds(10),10,10)));}try(var b=new JsonStorage(directory.resolve("json"),1048576,false)){var after=b.snapshot();if(point==JsonStorage.Point.AFTER_RENAME){assertEquals(5,after.recovery().get(PLAYER,"global").lifetimeReward());assertEquals(5,after.profiles().getFirst().systemScore());}else assertEquals(before,after);}}
 @Test void corruptedRecoveryFailsClosed()throws Exception{try(var b=StorageFixtures.local(directory,StorageType.SQLITE,false)){complete(b,directory);try(var c=((SqlStorage)b).connect();var s=c.createStatement()){s.executeUpdate("UPDATE dr_recovery SET revision=revision+1");}}assertThrows(Exception.class,()->StorageFixtures.local(directory,StorageType.SQLITE,false));try(var b=StorageFixtures.local(directory,StorageType.JSON,false)){complete(b,directory);}var p=directory.resolve("json/state.json");Files.writeString(p,Files.readString(p).replace("rehabilitation","corrupted"));assertThrows(Exception.class,()->StorageFixtures.local(directory,StorageType.JSON,false));}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void migrationPreservesEverything(StorageType type)throws Exception{StorageFixtures.resources(directory);Files.writeString(directory.resolve("storage.yml"),StorageFixtures.config(type));Files.writeString(directory.resolve("target.yml"),StorageFixtures.config(type==StorageType.JSON?StorageType.SQLITE:StorageType.JSON));StorageSnapshot before;try(var b=StorageManager.create(directory,Settings.load(directory),Map.of(),false)){before=complete(b,directory);}var result=new StorageMigration().migrate(directory,directory.resolve("target.yml"),directory.resolve("backups"),Map.of());assertEquals(before,new SnapshotCodec().decode(Files.readAllBytes(result.backupDirectory().resolve("VERIFIED.json"))).snapshot());try(var b=StorageManager.create(directory,Settings.load(directory),Map.of(),false)){assertEquals(before,b.snapshot());}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void disabledRecoveryPausesOfflineProgramsBeforeReadiness(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.disabled(b,directory);}}
 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void automaticEnrollmentUsesSameAtomicEligibility(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryContract.automatic(b,directory);}}

 @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void unfinishedProgressSurvivesRestartAndNewSession(StorageType type)throws Exception{StorageSnapshot before;try(var b=StorageFixtures.local(directory,type,false)){seed(b,directory,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));b.recover(request(Command.START,NOW));b.recover(sample(NOW,0,0));b.recover(sample(NOW.plusSeconds(4),4,4));before=b.snapshot();}try(var b=StorageFixtures.local(directory,type,false)){assertEquals(before,b.snapshot());b.tiers(TierConfiguration.load(directory));b.recovery(rules(RecoveryRules.Type.ACTIVE_PLAYTIME));UUID session=UUID.randomUUID();b.recover(request(UUID.randomUUID(),Command.SAMPLE,NOW.plusSeconds(5),0,0,session,true,ZERO,"",0,Set.of()));var done=b.recover(request(UUID.randomUUID(),Command.SAMPLE,NOW.plusSeconds(11),6,6,session,false,ZERO,"",0,Set.of()));assertEquals(5,done.profile().systemScore());assertEquals(1,done.state().rewards().size());}}

}
